import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  BarController,
  LineElement,
  PointElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';
import { Chart } from 'react-chartjs-2';
import ChartDataLabels from 'chartjs-plugin-datalabels';
import { Typography, Box } from "@mui/material";

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  BarController,
  LineElement,
  PointElement,
  Title,
  Tooltip,
  Legend,
  ChartDataLabels);

const options = {
  responsive: true,
  maintainAspectRatio: false, 
  scales: {
    x: {
      grid: {
        display: false
      }
    },
    y: {
      grid: {
        display: false
      }
    },
  },
  plugins: {
    legend: {
      position: "top",
      display: true,
    },
    title: {
      // display: true,
    },
    datalabels: {
      display: true,
      color: 'black', // 레이블 색상
      anchor: 'end', // 위치: 'start', 'center', 'end'
      align: 'top', // 정렬: 'top', 'bottom', 'center'
      formatter: (value) => value, // 값 포맷팅
    },
  },
};


const legendMargin = {
  id: 'legendMargin',
  beforeInit(chart, legend, options) {
    const fitValue = chart.legend.fit;
    chart.legend.fit = function() {
      fitValue.bind(chart.legend)();
      // 여기서 간격 조절 (height + 20px)
      this.height += 20; 
    };
  }
};

const ChartJs = ({ months, companys, sales }) => {

  const data = {
  labels: [months[0]+"월", months[1]+"월", months[2]+"월"],
  datasets: [
    {
      type: 'bar',
      label: '업체등록수',
      data: companys,
      borderColor: 'rgba(242, 48, 232, 0.5)',
      backgroundColor: "rgba(242, 48, 232, 0.5)",
      barThickness: 25, // 20px로 고정

    },
    {
      type: 'bar',
      label: '영업등록수',
      data: sales,
      backgroundColor: "rgba(42, 62, 250, 0.5)",
      barThickness: 25, // 20px로 고정
      yAxisID: 'y', // 기본 y축
    },
  ],
};
  return (
    <Box
      display="flex"
      flexDirection="column"
      justifyContent="center"
      alignItems="center"
    >
      <Typography mb="20px" sx={{fontSize: "18px"}}>최근 3개월 영업활동 현황</Typography>
      <Box 
        display="flex"
        flexDirection="column"
        justifyContent="center"
        alignItems="center"
        width="98%"
        height="200px"
      >
        <Chart  data={data} options={options} plugins={[legendMargin]} />
      </Box>
    </Box>
  )
};

export default ChartJs;

