import { useState } from "react";
import {
  Box,
  Typography
} from "@mui/material";
import WidgetWrapper from "components/WidgetWrapper";
import SearchSalesNormal from "./SearchSalesNormal"
import SearchSalesLapse from "./SearchSalesLapse"
import Tabs from '@mui/material/Tabs';
import Tab from '@mui/material/Tab';
import { useDispatch, useSelector } from "react-redux";

import { setPosts, setSalesPageMenuMode, setSearchMode } from "state";

const SearchSalesPannel = () => {

  const dispatch = useDispatch()
  const mainUser = useSelector((state) => state.mainUser)

  const [searchType, setSearchType] = useState("normal");

  const handleChange = (e, newValue) => {
    dispatch(setPosts({ posts: [] }))
    dispatch(setSearchMode(newValue))
    setSearchType(newValue)
    dispatch(setSalesPageMenuMode("search"))
  }

  return (
    <WidgetWrapper>
      <Typography
        color={"#555"}
        mb={!mainUser ? "15px" : "0"}
        sx={{
          fontWeight: "700",
          fontSize: "18px",
        }}
      >
        영업관리
      </Typography>
      {mainUser ? 
        <Typography
          color={"#555"}
          mb={"15px"}
          sx={{
            fontSize: "14px",
            color: "red"
          }}
        >
          (mainUser.name님의 동행자 모드입니다)
        </Typography>
      : null}

      <Box sx={{ borderBottom: 1, borderColor: 'divider'}}>
        <Tabs
          value={searchType}
          onChange={handleChange}
          slotProps={{
            indicator: { sx: { height: '4px' } }
          }}>
          <Tab sx={{ fontSize: "14px" }} value={"normal"}  label="일반" />
          <Tab sx={{fontSize: "14px"}} value={"lapse"} label="경과기간"/>
        </Tabs>
      </Box>
      <Box
        sx={{ mt: "25px" }}
      >
        {
          searchType === "normal" ? <SearchSalesNormal/> : <SearchSalesLapse/>
        }
      </Box>
    </WidgetWrapper>
  )

};

export default SearchSalesPannel;
