import { useState, useRef, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  Box,
  Button,
  TextField,
  useMediaQuery,
  Typography,
} from "@mui/material";
import MenuItem from "@mui/material/MenuItem";
import FormControl from "@mui/material/FormControl";
import * as yup from "yup";
import WidgetWrapper from "components/WidgetWrapper";
import dayjs from "dayjs";

import { Formik } from "formik";

import { setEditData, updatePosts, setSalesPageMenuMode, addPost } from "state";

const inputSchema = yup.object().shape({
  companyName: yup.string().required("required"),
  registNo: yup.string(),
  ceo: yup.string(),
  year: yup.string(),
  age: yup.string(),
  companyType: yup.string(),
  salesType: yup.string(),
  employees: yup.number(),
  grossRevenue: yup.string(),
  netProfit: yup.string(),
  suspenseAccount: yup.string(),
  retainedEarnings: yup.string(),
  industry: yup.string(),
  address: yup.string(),
  phone: yup.string(),
  groupInsu: yup.string(),
  companyInsu: yup.string(),
  companion: yup.string(),
  group: yup.string(),
  status: yup.string(),
});

const RegistCompanyWidget = () => {
  const editData = useSelector((state) => state.editData);
  const token = useSelector((state) => state.token);
  const user = useSelector((state) => state.user);
  const mainUser = useSelector((state) => state.mainUser);

  const initialValues = {
    companyName: editData ? editData.companyName : "",
    registNo: editData ? editData.registNo : "",
    ceo: editData ? editData.ceo : "",
    year: "",
    age: editData ? editData.age : "",
    companyType: editData ? editData.companyType : "",
    salesType: editData ? editData.salesType : "",
    employees: editData ? editData.employees : "",
    grossRevenue: editData ? editData.grossRevenue : "",
    netProfit: editData ? editData.netProfit : "",
    suspenseAccount: editData ? editData.suspenseAccount : "",
    retainedEarnings: editData ? editData.retainedEarnings : "",
    industry: editData ? editData.industry : "",
    address: editData ? editData.address : "",
    phone: editData ? editData.phone : "",
    groupInsu: editData ? editData.groupInsu : "",
    companyInsu: editData ? editData.companyInsu : "",
    companion: editData ? editData.companion : "",
    group: editData ? editData.group : "",
    status: editData ? editData.status : "",
  };

  const editDataCompanion = editData
    ? user.companion.find((value) => value.name === editData.companion)
    : null;

  const [companyVerified, setCompanyVerified] = useState(false);
  const [btnDisabled, setBtnDisabled] = useState(true);
  const [selectedCompanion, setSelectedCompanion] = useState(
    editDataCompanion ? editDataCompanion : { name: "", groups: [] },
  );

  const isMobile = useMediaQuery("(max-width:600px)");
  const dispatch = useDispatch();
  const formRef = useRef();
  const scrollRef = useRef();

  const companyInputChange = (values, setFieldValue, e) => {
    if (e.currentTarget.value !== "" || values.registNo !== "") {
      setBtnDisabled(false);
    } else if (e.currentTarget.value === "" && values.registNo === "") {
      setBtnDisabled(true);
      setCompanyVerified(false);
    }

    setFieldValue("companyName", e.currentTarget.value);
  };

  // const registNoInputChange = (values, setFieldValue, e) => {
  //   const target = e.currentTarget;

  //   if (target.value !== "" || values.companyName !== "") {
  //     setBtnDisabled(false);
  //   } else if (target.value === "" && values.companyName === "") {
  //     setBtnDisabled(true);
  //     setCompanyVerified(false);
  //   }

  //   let value = target.value.replace(/[^0-9]/g, "");

  //   // 정규식을 이용한 하이픈 분기 처리
  //   if (value.length < 4) {
  //     target.value = value;
  //   } else if (value.length < 6) {
  //     target.value = value.replace(/(\d{3})(\d{1,2})/, "$1-$2");
  //   } else if (value.length < 12) {
  //     target.value = value.replace(/(\d{3})(\d{2})(\d{1,5})/, "$1-$2-$3");
  //   }

  //   setFieldValue("registNo", target.value);
  // };

  function checkBizId(bizID) {
    // 1. 하이픈 제거 및 숫자 여부 확인
    const regExp = /-/g;
    let bNo = String(bizID).replace(regExp, "");
    if (bNo.length !== 10) return false;

    // 2. 국세청 유효성 검사 알고리즘 적용
    const checkID = [1, 3, 7, 1, 3, 7, 1, 3, 5, 1];
    let chkSum = 0;

    for (let i = 0; i < 9; i++) {
      chkSum += parseInt(bNo.charAt(i), 10) * checkID[i];
    }

    // 열 번째 자릿수 검증
    const lastDigit = parseInt(bNo.charAt(9), 10);
    const sumMod = Math.floor((parseInt(bNo.charAt(8), 10) * checkID[8]) / 10);
    const chkValue = (chkSum + sumMod) % 10;
    const result = (10 - chkValue) % 10;

    return lastDigit === result;
  }

  const companyVerify = async (values) => {
    if (values.registNo !== "") {
      if (!checkBizId(values.registNo)) {
        alert("유효하지 않은 사업자등록번호입니다.");
        return;
      }
    }

    if (values.registNo !== "" && values.companyName === "") {
      alert("사업자등록번호 입력시 회사명도 함께 입력되어야 합니다.");
      return;
    }

    values.userId = user._id;

    const response = await fetch(
      "http://3.37.116.103:3500/data/companyVerify",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(values),
      },
    );

    if (!response.ok) {
      const error = await response.json();
      alert(error);
      return;
    }

    const result = await response.json();

    alert(result.msg);
    setCompanyVerified(true);
  };

  const saveCompany = async (values, resetForm) => {

    if (values.companyName === "") {
      alert("회사명은 반드시 입력해야 합니다");
      return;
    }

    try {
      values.userId = user._id;

      const response = await fetch(
        "http://3.37.116.103:3500/data/saveCompany",
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify(values),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }

      const saved = await response.json();

      setCompanyVerified(false);
      setBtnDisabled(true);
      resetForm();
      dispatch(addPost(saved))
      dispatch(setSalesPageMenuMode("search"));
    } catch (error) {
      alert(error.message);
    }
  };

  const updateCompany = async (values, resetForm) => {
    try {
      values.userId = user._id;
      values.companyId = editData ? editData._id : "";
      values.originalCompanyName = editData ? editData.companyName : "";
      values.originalRegistNo = editData ? editData.registNo : "";

      const response = await fetch(
        "http://3.37.116.103:3500/data/updateCompany",
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify(values),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }
      const result = await response.json();

      dispatch(updatePosts(result));
      dispatch(setEditData(null));
      
      setCompanyVerified(false);
      setBtnDisabled(true);
      resetForm();
      dispatch(setSalesPageMenuMode("search"));

    } catch (error) {
      alert(error.msg);
    }
  };

  const cancel = (resetForm) => {
    setCompanyVerified(false);
    setBtnDisabled(true);
    dispatch(setEditData(null));
    resetForm();
  };

const handleInputChange = (name, setFieldValue, e) => {
  const target = e.target;
  let originalValue = target.value;
  
  // 1. 문자를 지우기 전, 현재 커서 위치 저장
  let cursorPosition = target.selectionStart;

  // 2. 숫자와 마이너스만 남기고 정제하기
  let value = originalValue.replace(/[^0-9-]/g, "");

  // 맨 앞의 마이너스만 유지하고, 중간/끝에 들어간 마이너스는 제거
  if (value.startsWith('-')) {
    value = '-' + value.slice(1).replace(/-/g, '');
  } else {
    value = value.replace(/-/g, '');
  }

  // [중요] 사용자가 중간에 문자를 입력해서 지워진 경우, 커서 위치를 보정
  if (originalValue.length !== value.length) {
    cursorPosition = Math.max(0, cursorPosition - (originalValue.length - value.length));
  }

  // 3. 기존 로직 (나이/연도 계산)
  // 마이너스 부호만 딸랑 있을 때는 계산에서 제외 (숫자가 채워질 때만 계산)
  const numericValue = parseInt(value, 10);

  if (name === "year") {
    if (value === "" || value === "-" || isNaN(numericValue)) {
      setFieldValue("age", "");
    } else {
      let age = dayjs().year() - numericValue;
      setFieldValue("age", age);
    }
  }
  
  if (name === "age") {
    if (value === "" || value === "-" || isNaN(numericValue)) {
      setFieldValue("year", "");
    } else {
      let year = dayjs().year() - numericValue;
      setFieldValue("year", year);
    }
  }

  // 4. 상태(State) 업데이트
  setFieldValue(name, value);

  // 5. 브라우저 렌더링 직후 커서 위치를 원래대로 복구
  requestAnimationFrame(() => {
    // 텍스트 필드가 언마운트되거나 포커스를 잃지 않은 경우에만 커서 적용
    if (document.activeElement === target) {
      target.setSelectionRange(cursorPosition, cursorPosition);
    }
  });
}

  useEffect(() => {
    const elementTop = scrollRef.current.offsetTop;

    const offsetPosition = isMobile ? elementTop - 100 : elementTop - 150

    window.scrollTo({
      top: offsetPosition,
      behavior: 'smooth', // 부드럽게 이동
    });
  }, [isMobile])

  return (
    <Formik
      initialValues={initialValues}
      validationSchema={inputSchema}
      innerRef={formRef}
    >
      {({
        values,
        errors,
        touched,
        handleBlur,
        handleChange,
        handleSubmit,
        setFieldValue,
        resetForm,
        submitForm,
      }) => (
        <Box ref={scrollRef}>
          <Typography mb="20px" sx={{ fontSize: "18px", fontWeight: 600 }}>
            {editData ? "업체정보 수정" : "업체정보 등록"}
          </Typography>
          <form onSubmit={handleSubmit}>
            <Box display="grid" gap="15px">
              <Box
                display="grid"
                gap="20px"
                gridTemplateColumns="repeat(4, minmax(0, 1fr))"
              >
                <TextField
                  disabled={mainUser? true : false }
                  label="회사명*"
                  onBlur={handleBlur}
                  onChange={(e) => companyInputChange(values, setFieldValue, e)}
                  value={values.companyName}
                  name="companyName"
                  sx={{ gridColumn: isMobile ? "span 4" : "span 2" }}
                />
                <TextField
                  disabled={mainUser? true : false }
                  label="사업자등록번호"
                  onBlur={handleBlur}
                  onChange={(e) =>
                    handleInputChange("registNo", setFieldValue, e)
                  }
                  value={values.registNo}
                  name="registNo"
                  sx={{
                    gridColumn: isMobile ? "span 4" : "span 1"
                  }}
                  slotProps={{
                    htmlInput: {
                      inputMode: 'numeric',
                      pattern: '[0-9]*'
                    }
                  }}
                />
                {!editData ? (
                  <Button
                    onClick={() => companyVerify(values)}
                    disabled={btnDisabled}
                    sx={{
                      p: "1rem",
                      backgroundColor: "#0073E6",
                      color: "#fff",
                      "&:hover": { backgroundColor: "#5299e0" },
                      "&.Mui-disabled": {
                        backgroundColor: "#ddd",
                        color: "#666",
                      },
                      gridColumn: isMobile ? "span 4" : "span 1",
                    }}
                  >
                    등록여부확인
                  </Button>
                ) : null}
              </Box>
              <Box
                display="grid"
                gap="20px"
                gridTemplateColumns="repeat(4, minmax(0, 1fr))"
              >
                <TextField
                  disabled={mainUser? true : false }
                  label="대표"
                  onBlur={handleBlur}
                  onChange={handleChange}
                  value={values.ceo}
                  name="ceo"
                  error={Boolean(touched.ceo) && Boolean(errors.ceo)}
                  helperText={touched.ceo && errors.ceo}
                  sx={{ gridColumn: isMobile ? "span 4" : "span 1" }}
                />
                <Box
                  gridColumn={isMobile ? "span 4" : "span 1"}
                  display="grid"
                  gridTemplateColumns="repeat(2, minmax(0, 1fr))"
                  gap="15px"
                >
                  <TextField
                    disabled={mainUser? true : false }
                    label="출생년도"
                    onBlur={handleBlur}
                    onChange={(e) =>
                      handleInputChange("year", setFieldValue, e)
                    }
                    value={values.year}
                    name="year"
                    slotProps={{
                      htmlInput: {
                        inputMode: 'numeric',
                        pattern: '[0-9]*'
                      }
                    }}
                  />
                  <TextField
                    disabled={mainUser? true : false }
                    label="나이"
                    onBlur={handleBlur}
                    onChange={(e) => handleInputChange("age", setFieldValue, e)}
                    value={values.age}
                    name="age"
                    slotProps={{
                      htmlInput: {
                        inputMode: 'numeric',
                        pattern: '[0-9]*'
                      }
                    }}
                  />
                </Box>
                <TextField
                  disabled={mainUser? true : false }
                  label="직원수"
                  onBlur={handleBlur}
                  onChange={(e) =>
                    handleInputChange("employees", setFieldValue, e)
                  }
                  value={values.employees}
                  name="employees"
                  sx={{
                    gridColumn: isMobile ? "span 4" : "span 1",
                  }}
                  slotProps={{
                      htmlInput: {
                        inputMode: 'numeric',
                        pattern: '[0-9]*'
                      }
                    }}
                />
                <FormControl
                  sx={{ gridColumn: isMobile ? "span 4" : "span 1" }}
                >
                  <TextField
                    disabled={mainUser? true : false }
                    select
                    label="기업유형"
                    name="companyType"
                    value={values.companyType}
                    onChange={handleChange}
                  >
                    <MenuItem value={"법인"}>법인</MenuItem>
                    <MenuItem value={"외감"}>외감</MenuItem>
                    <MenuItem value={"개인"}>개인</MenuItem>
                    <MenuItem value={"기타"}>기타</MenuItem>
                  </TextField>
                </FormControl>
              </Box>
              <Box
                display="grid"
                gap="20px"
                gridTemplateColumns="repeat(4, minmax(0, 1fr))"
              >
                <TextField
                  disabled={mainUser? true : false }
                  label="매출액(백만)"
                  onBlur={handleBlur}
                  onChange={(e) =>
                    handleInputChange("grossRevenue", setFieldValue, e)
                  }
                  value={values.grossRevenue}
                  name="grossRevenue"
                  sx={{
                    gridColumn: isMobile ? "span 4" : "span 1",
                  }}
                />

                <TextField
                  disabled={mainUser? true : false }
                  label="순이익(백만)"
                  onBlur={handleBlur}
                  onChange={(e) =>
                    handleInputChange("netProfit", setFieldValue, e)
                  }
                  value={values.netProfit}
                  name="netProfit"
                  sx={{
                    gridColumn: isMobile ? "span 4" : "span 1",
                  }}
                />
                <TextField
                  disabled={mainUser? true : false }
                  label="가지급금"
                  onBlur={handleBlur}
                  onChange={(e) =>
                    handleInputChange("suspenseAccount", setFieldValue, e)
                  }
                  value={values.suspenseAccount}
                  name="suspenseAccount"
                  sx={{
                    gridColumn: isMobile ? "span 4" : "span 1",
                  }}
                />
                <TextField
                  disabled={mainUser? true : false }
                  label="이익잉여금(백만)"
                  onBlur={handleBlur}
                  onChange={(e) =>
                    handleInputChange("retainedEarnings", setFieldValue, e)
                  }
                  value={values.retainedEarnings}
                  name="retainedEarnings"
                  sx={{
                    gridColumn: isMobile ? "span 4" : "span 1",
                  }}
                />
              </Box>
              <Box
                display="grid"
                gap="20px"
                gridTemplateColumns="repeat(4, minmax(0, 1fr))"
              >
                <FormControl
                  sx={{ gridColumn: isMobile ? "span 4" : "span 1" }}
                >
                  <TextField
                    disabled={mainUser? true : false }
                    select
                    label="단체보험"
                    name="groupInsu"
                    value={values.groupInsu}
                    onChange={handleChange}
                  >
                    <MenuItem value={""}>미확인</MenuItem>
                    <MenuItem value={"Y"}>Y</MenuItem>
                    <MenuItem value={"N"}>N</MenuItem>
                  </TextField>
                </FormControl>
                <FormControl
                  sx={{ gridColumn: isMobile ? "span 4" : "span 1" }}
                >
                  <TextField
                    disabled={mainUser? true : false }
                    select
                    label="법인명의"
                    name="companyInsu"
                    value={values.companyInsu}
                    onChange={handleChange}
                  >
                    <MenuItem value={""}>미확인</MenuItem>
                    <MenuItem value={"Y"}>Y</MenuItem>
                    <MenuItem value={"N"}>N</MenuItem>
                  </TextField>
                </FormControl>
              </Box>
              <Box
                display="grid"
                gap="20px"
                gridTemplateColumns="repeat(4, minmax(0, 1fr))"
              >
                <TextField
                  disabled={mainUser? true : false }
                  multiline
                  label="업종"
                  onBlur={handleBlur}
                  onChange={handleChange}
                  value={values.industry}
                  name="industry"
                  sx={{ gridColumn: isMobile ? "span 4" : "span 2" }}
                />
                <Box
                  gridColumn={isMobile ? "span 4" : "span 2"}
                  display="grid"
                  gap="20px"
                  gridTemplateColumns="repeat(4, minmax(0, 1fr))"
                >
                  <TextField
                    disabled={mainUser? true : false }
                    multiline
                    label="주소"
                    onBlur={handleBlur}
                    onChange={handleChange}
                    value={values.address}
                    name="address"
                    sx={{ gridColumn: isMobile ? "span 4" : "span 3" }}
                  />
                  <TextField
                    disabled={mainUser? true : false }
                    label="전화번호"
                    onBlur={handleBlur}
                    onChange={(e) => handleInputChange("phone", setFieldValue, e)}
                    value={values.phone}
                    name="phone"
                    sx={{ gridColumn: isMobile ? "span 4" : "span 1" }}
                    slotProps={{
                      htmlInput: {
                        inputMode: 'numeric',
                        pattern: '[0-9]*'
                      }
                    }}
                  />
                </Box>
              </Box>
              <Box
                display="grid"
                gap="20px"
                gridTemplateColumns="repeat(4, minmax(0, 1fr))"
              >
                <FormControl
                  sx={{ gridColumn: isMobile ? "span 4" : "span 1" }}
                >
                  <TextField
                    disabled={mainUser? true : false }
                    select
                    label="영업유형"
                    name="salesType"
                    value={values.salesType}
                    onBlur={handleBlur}
                    onChange={handleChange}
                    error={
                      Boolean(touched.salesType) && Boolean(errors.salesType)
                    }
                    helperText={touched.salesType && errors.salesType}
                  >
                    <MenuItem value={"개척"}>개척</MenuItem>
                    <MenuItem value={"타겟"}>타겟</MenuItem>
                    <MenuItem value={"TA"}>TA</MenuItem>
                    <MenuItem value={"소개"}>소개</MenuItem>
                  </TextField>
                </FormControl>
                <FormControl
                  fullWidth
                  sx={{ gridColumn: isMobile ? "span 4" : "span 1" }}
                >
                  <TextField
                    disabled={mainUser? true : false }
                    select
                    value={values.status}
                    label="영업상태"
                    name="status"
                    onBlur={handleBlur}
                    onChange={handleChange}
                    error={Boolean(touched.status) && Boolean(errors.status)}
                    helperText={touched.status && errors.status}
                  >
                    <MenuItem value={"등록"}>등록</MenuItem>
                    <MenuItem value={"재방"}>재방</MenuItem>
                    <MenuItem value={"상"}>상</MenuItem>
                    <MenuItem value={"중"}>중</MenuItem>
                    <MenuItem value={"하"}>하</MenuItem>
                    <MenuItem value={"종료"}>종료</MenuItem>
                  </TextField>
                </FormControl>
                <FormControl
                  fullWidth
                  sx={{ gridColumn: isMobile ? "span 4" : "span 1" }}
                >
                  <TextField
                    disabled={mainUser? true : false }
                    select
                    value={values.companion}
                    label="공동영업"
                    name="companion"
                    onBlur={handleBlur}
                    onChange={(e) => {
                      setFieldValue("companion", e.target.value);
                      const who = user.companion.find(
                        (u) => u.name === e.target.value,
                      );
                      setSelectedCompanion(who);
                    }}
                    error={
                      Boolean(touched.companion) && Boolean(errors.companion)
                    }
                    helperText={touched.companion && errors.companion}
                  >
                    {user.companion.map((item) => (
                      <MenuItem value={item.name}>{item.name}</MenuItem>
                    ))}
                  </TextField>
                </FormControl>
                <FormControl
                  fullWidth
                  sx={{ gridColumn: isMobile ? "span 4" : "span 1" }}
                >
                  <TextField
                    disabled={mainUser? true : false }
                    select
                    value={values.group}
                    label="그룹"
                    name="group"
                    onBlur={handleBlur}
                    onChange={(e) => setFieldValue("group", e.target.value)}
                    error={Boolean(touched.group) && Boolean(errors.group)}
                    helperText={touched.group && errors.group}
                  >
                    {selectedCompanion.groups.map((item) => (
                      <MenuItem value={item}>{item}</MenuItem>
                    ))}
                  </TextField>
                </FormControl>
              </Box>
            </Box>
            {/* BUTTONS */}
            <Box
              display="flex"
              justifyContent={"center"}
              alignItems={"center"}
              gap="10px"
            >
              <Button
                fullWidth
                disabled={
                  editData
                    ? false
                    : companyVerified && values.company !== ""
                      ? false
                      : true
                }
                sx={{
                  m: "2rem 0",
                  p: "1rem",
                  backgroundColor: "#0073E6",
                  color: "#fff",
                  "&:hover": { backgroundColor: "#5299e0" },
                  "&.Mui-disabled": {
                    backgroundColor: "#ddd",
                    color: "#666",
                  },
                }}
                onClick={
                  editData
                    ? () => updateCompany(values, resetForm)
                    : () => saveCompany(values, resetForm)
                }
              >
                {editData ? "수정" : "저장"}
              </Button>
              {editData ? null : 
                <Button
                  disabled={mainUser? true : false }
                  fullWidth
                  sx={{
                    m: "2rem 0",
                    p: "1rem",
                    backgroundColor: "#0073E6",
                    color: "#fff",
                    "&:hover": { backgroundColor: "#5299e0" },
                    "&.Mui-disabled": {
                      backgroundColor: "#ddd",
                      color: "#666",
                    },
                  }}
                  onClick={() => cancel(resetForm)}
                >
                  초기화
                </Button>
              }
              <Button
                disabled={mainUser? true : false }
                fullWidth
                sx={{
                  m: "2rem 0",
                  p: "1rem",
                  backgroundColor: "#0073E6",
                  color: "#fff",
                  "&:hover": { backgroundColor: "#5299e0" },
                  "&.Mui-disabled": {
                    backgroundColor: "#ddd",
                    color: "#666",
                  },
                }}
                onClick={() => {
                  dispatch(setSalesPageMenuMode("search"))
                  dispatch(setEditData(null))
                }}
              >
                취소
              </Button>
            </Box>
          </form>
        </Box>
      )}
    </Formik>
  );
};

export default RegistCompanyWidget;
