import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import { Typography, Box, useMediaQuery } from "@mui/material";

const DoughnutWidget = ({groupNames, groupTotalNums}) => {

  const isMobile = useMediaQuery("(max-width:600px)");
  
  ChartJS.register(ArcElement, Tooltip, Legend);

  const data = {
    labels: groupNames,
    datasets: [
      {
        label: '영업 수',
        data: groupTotalNums,
        backgroundColor: [
          'rgba(255, 99, 132, 0.6)',
          'rgba(54, 162, 235, 0.6)',
          'rgba(255, 206, 86, 0.6)',
          'rgba(102, 244, 100, 0.6)',
        ],
        borderColor: [
          'rgba(255, 99, 132, 1)',
          'rgba(54, 162, 235, 1)',
          'rgba(255, 206, 86, 1)',
          'rgba(102, 244, 100, 1)',
        ],
        borderWidth: 2,
      },
    ],
  };

  // 차트 옵션 설정 (필요시 크기 조절 등)
  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
        labels: {
        // 방법 B: 범례 글자 주변의 여백 늘리기
        padding: 15, // 💡 기본값(10)보다 크게 주면 범례 아래쪽 간격이 벌어집니다.
      }
      },
    },
    radius: isMobile ? "95%": "80%"
  }
  
  return (
    <Box
      display="flex"
      flexDirection="column"
      justifyContent="center"
      alignItems="center"
    >
      <Typography mb="20px" sx={{ fontSize: "18px" }}>영업횟수 상위 4개 그룹</Typography>
      <Box
        display="flex"
        flexDirection="column"
        justifyContent="center"
        alignItems="center"
        width="98%"
        height="270px"
      >
        <Doughnut data={data} options={options} />
      </Box>
    </Box>
  )
}

export default DoughnutWidget