import {
  Box,
  Typography,
  Button,
  TextField,
} from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import { updatePosts } from "state";
import ClearIcon from "@mui/icons-material/Clear";
import Dialog from "@mui/material/Dialog";
import DialogContent from "@mui/material/DialogContent";
import DialogTitle from "@mui/material/DialogTitle";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { DatePicker } from "@mui/x-date-pickers/DatePicker";
import FlexBetween from "components/FlexBetween";
import MenuItem from "@mui/material/MenuItem";
import EditOutlinedIcon from "@mui/icons-material/EditOutlined";
import Dropzone from "react-dropzone";
import dayjs from "dayjs";
import { Formik } from "formik";
import * as yup from "yup";

const inputSchema = yup.object().shape({
  date: yup.string().required("required"),
  doc: yup.string(),
  savedDocName: yup.string(),
  contents: yup.string(),
  salesStatus: yup.string(),
});

const SalesDialog = ({ setOpen, open, setEditData, setSelectedItem, post }) => {
  const user = useSelector((state) => state.user);
  const token = useSelector((state) => state.token);
  const item = useSelector((state) => state.editData);

  const dispatch = useDispatch();

  const initialValues = {
    date: item
      ? dayjs(item.date).format("YYYY-MM-DD")
      : dayjs(new Date()).format("YYYY-MM-DD"),
    doc: item ? item.doc : "",
    savedDocName: item ? item.savedDocName : "",
    contents: item ? item.contents : "",
    salesStatus: item ? item.salesStatus : "재방",
  };

  const cancel = (resetForm) => {
    resetForm();
    setOpen(false);
  };

  const handleFormSubmit = async (values, onFormikProps) => {
    if (!item) {
      await saveSales(values);
    } else {
      await updateSales(values);
    }

    dispatch(setEditData(null));
    setSelectedItem(null);
    setOpen(false);
    onFormikProps.resetForm();
  };

  const saveSales = async (values, onSubmitProps) => {
    if (values.contents === "") {
      alert("내용은 반드시 입력해야 합니다.");
      return;
    }

    const formData = new FormData();

    formData.append("userId", user._id);
    formData.append("companyId", post._id);

    for (let value in values) {
      formData.append(value, values[value]);
    }

    const response = await fetch("http://3.37.116.103:3500/data/saveSales", {
      method: "POST",
      body: formData,
      headers: { Authorization: `Bearer ${token}` },
    });

    if (!response.ok) {
      const error = await response.json();
      alert(error);
      return;
    }

    const data = await response.json();

    dispatch(updatePosts(data));
  };

  const updateSales = async (values, onSubmitProps) => {
    const formData = new FormData();

    formData.append("userId", user._id);
    formData.append("companyId", post._id);
    formData.append("salesId", item._id);
    formData.append("originalSavedDocName", item.savedDocName);

    for (let value in values) {
      formData.append(value, values[value]);
    }

    const response = await fetch("http://3.37.116.103:3500/data/updateSales", {
      method: "POST",
      body: formData,
      headers: { Authorization: `Bearer ${token}` },
    });

    if (!response.ok) {
      const error = await response.json();
      alert(error);
      return;
    }

    const data = await response.json();

    dispatch(updatePosts(data));
  };

  const handleClose = () => {
    setOpen(false);
  };

  return (
    <Dialog open={open} onClose={handleClose} role="alertdialog">
      <DialogTitle id="alert-dialog-title" fontSize={"18px"}>
        {"영업정보 등록"}
      </DialogTitle>
      <DialogContent>
        <Formik
          onSubmit={handleFormSubmit}
          initialValues={initialValues}
          validationSchema={inputSchema}
        >
          {({
            values,
            errors,
            touched,
            handleBlur,
            handleChange,
            handleSubmit,
            setFieldValue,
            resetForm,
            submitForm,
          }) => (
            <>
              <form onSubmit={handleSubmit}>
                <Box display="flex" flexDirection="column" gap="15px" mt="15px">
                  <Box>
                    <LocalizationProvider dateAdapter={AdapterDayjs}>
                      <DatePicker
                        sx={{ width: "100%" }}
                        label="날짜*"
                        format="YYYY-MM-DD"
                        name={"date"}
                        value={dayjs(values.date)}
                        onChange={async (value) => {
                          const date = dayjs(value).format("YYYY-MM-DD");

                          const today = dayjs(new Date()).format("YYYY-MM-DD");

                          if (date !== "Invalid Date" && today < date) {
                            values.date = dayjs(new Date()).format(
                              "YYYY-MM-DD",
                            );
                            alert("오늘 이후 날짜는 미리 입력할 수 없습니다");
                            return;
                          }

                          setFieldValue("date", date.toString());
                        }}
                        slotProps={{
                          field: { clearable: true },
                        }}
                        error={Boolean(touched.date) && Boolean(errors.date)}
                        helperText={touched.date && errors.date}
                      />
                    </LocalizationProvider>
                  </Box>
                  <Box>
                    <TextField
                      fullWidth
                      multiline
                      label="주요내용"
                      onBlur={handleBlur}
                      onChange={handleChange}
                      value={values.contents}
                      name="contents"
                      sx={{ gridColumn: "span 2" }}
                    />
                  </Box>
                  <Box
                    display="flex"
                    justifyContent={"center"}
                    alignItems={"center"}
                    gap="5px"
                    border={`1px solid #ddd`}
                    borderRadius="5px"
                    // p="1rem"
                    sx={{ position: "relative" }}
                    p="5px"
                  >
                    <Box
                      component="label"
                      p="5px"
                      sx={{
                        fontSize: "10px",
                        color: "text.secondary",
                        position: "absolute",
                        top: "-15px",
                        left: "10px",
                        background: "#fff",
                      }}
                    >
                      제공문서
                    </Box>
                    <Dropzone
                      acceptedFiles=".jpg, .jpeg, .png, .pdf"
                      multiple={false}
                      onDrop={(acceptedFiles) => {
                        setFieldValue("doc", acceptedFiles[0]);
                      }}
                    >
                      {({ getRootProps, getInputProps }) => (
                        <Box
                          {...getRootProps()}
                          border={`2px dashed #ddd`}
                          // p="1rem"
                          sx={{
                            "&:hover": { cursor: "pointer" },
                            flexGrow: 1,
                            height: "50px",
                          }}
                          display="flex"
                          justifyContent={"start"}
                          alignItems={"center"}
                        >
                          <input {...getInputProps()} />
                          {!values.doc && values.savedDocName === "" ? (
                            <p style={{ paddingLeft: "15px", color: "#888" }}>
                              문서를 추가해 주세요
                            </p>
                          ) : (
                            <FlexBetween>
                              <Typography>
                                {values.doc
                                  ? values.doc?.name
                                  : values?.savedDocName.slice(
                                      values.savedDocName?.indexOf("___") + 3,
                                    )}
                              </Typography>
                              <EditOutlinedIcon />
                            </FlexBetween>
                          )}
                        </Box>
                      )}
                    </Dropzone>
                    {/* {values?.doc.name ? ( */}
                    {values.doc || values.savedDocName ? (
                      <ClearIcon
                        onClick={() => {
                          setFieldValue("doc", "");
                          setFieldValue("savedDocName", "");
                        }}
                      />
                    ) : null}
                  </Box>
                  <Box>
                    <TextField
                      fullWidth
                      select
                      value={values.salesStatus}
                      label="영업상태*"
                      name="salesStatus"
                      onChange={handleChange}
                    >
                      <MenuItem value={"재방"}>재방</MenuItem>
                      <MenuItem value={"상"}>상</MenuItem>
                      <MenuItem value={"중"}>중</MenuItem>
                      <MenuItem value={"하"}>하</MenuItem>
                      <MenuItem value={"종료"}>종료</MenuItem>
                    </TextField>
                  </Box>
                  {/* BUTTONS */}
                  <Box
                    display="flex"
                    justifyContent={"center"}
                    alignItems={"center"}
                    gap="30px"
                    mt="1rem"
                  >
                    <Button
                      fullWidth
                      type="submit"
                      sx={{
                        p: "1rem",
                        backgroundColor: "#0073E6",
                        color: "#fff",
                        "&:hover": { backgroundColor: "#5299e0" },
                        "&.Mui-disabled": {
                          backgroundColor: "#ddd",
                          color: "#666",
                        },
                      }}
                    >
                      {item ? "수정" : "저장"}
                    </Button>
                    <Button
                      fullWidth
                      sx={{
                        p: "1rem",
                        backgroundColor: "#0073E6",
                        color: "#fff",
                        "&:hover": { backgroundColor: "#5299e0" },
                        "&.Mui-disabled": {
                          backgroundColor: "#ddd",
                          color: "#666",
                        },
                      }}
                      onClick={() => cancel(resetForm)}
                    >
                      취소
                    </Button>
                  </Box>
                </Box>
              </form>
            </>
          )}
        </Formik>
      </DialogContent>
    </Dialog>
  );
};

export default SalesDialog;
