import {
  LocationOnOutlined,
} from "@mui/icons-material";
import RealEstateAgentOutlinedIcon from '@mui/icons-material/RealEstateAgentOutlined';
import { Box, Typography, Divider, useTheme, useMediaQuery } from "@mui/material";
import UserImage from "components/UserImage";
import Diversity3OutlinedIcon from '@mui/icons-material/Diversity3Outlined';
import WidgetWrapper from "components/WidgetWrapper";
import { useSelector } from "react-redux";
import { useCallback, useEffect, useState } from "react";
import ChartJs from "./Chart";
import DoughnutWidget from "./Doughnet";

const HomeWidget = () => {
  const [months, setMonths] = useState([0, 0, 0]);
  const [monthCompanies, setMonthCompanies] = useState([]);
  const [monthSales, setMonthSales] = useState([]);
  const [companyCount, setCompanyCount] = useState(0);
  const [salesCount, setSalesCount] = useState(0);
  const [weekCompanyCount, setWeekCompanyCount] = useState(0);
  const [weekSalesCount, setWeekSalesCount] = useState(0);
  const [groupNames, setGroupNames] = useState(new Array(4).fill(""));
  const [groupTotalNums, setGroupTotalNums] = useState(new Array(4).fill(0));
  const [totalGroupNums, setTotalGroupNums] = useState(0);

  const { palette } = useTheme();
  const dark = palette.neutral.dark;
  const medium = palette.neutral.medium;
  const main = palette.neutral.main;

  const user = useSelector((state) => state.user);
  const token = useSelector((state) => state.token);
  const mainUser = useSelector((state) => state.mainUser);
  const isMobile = useMediaQuery("(max-width:600px)");

  const getStatistics = useCallback(async (mainUser) => {
    try {
      const response = await fetch(
        `http://3.37.116.103:3500/data/statistics`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            userId: user._id,
            userName: user.name,
            mainUser,
          }),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }

      const data = await response.json();

      setCompanyCount(data.companyCount);
      setSalesCount(data.salesCount);
      setWeekCompanyCount(data.weekCompanyCount);
      setWeekSalesCount(data.weekSalesCount);
      setMonths(data.months);
      setMonthCompanies(data.monthCompany);
      setMonthSales(data.monthSales);

      setGroupNames([...data.groupNames, groupNames.slice(data.groupNames.length)].slice(0, 4))
      setGroupTotalNums([...data.groupTotalNums, groupTotalNums.slice(data.groupTotalNums.length)].slice(0, 4))
      setTotalGroupNums(data.totalGroupNums)
    } catch (error) {
      alert(error.message);
    }
  }, [])

  useEffect(() => {
    getStatistics(mainUser);
  }, [getStatistics, mainUser]);

  return (
    <WidgetWrapper>
      <Box
        display="flex"
        gap="20px"
        justifyContent={"start"}
        alignItems={"center"}
        p={isMobile ? "20px 0px" : "20px"}
      >
          <UserImage image={user.picturePath} />
          <Box>
            <Typography variant="h4" color={dark} fontWeight="500">
              {user.name}
          </Typography>
          {mainUser ? 
            <Typography fontSize="14px" color={"red"}>
              (mainUser.name님의 동행자 모드입니다)
            </Typography>
            : null}
          </Box>
      </Box>
      <Box
        display="grid"
        gridTemplateColumns={isMobile ? "1fr" : "1fr 1fr"}
        gap="50px"
        p={isMobile ? "20px 0px" : "20px"}
      >
        <Box
          display="flex"
          flexDirection={"column"}
          gap="15px"
        >
          <Divider />
          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
            >
            <Box
              display="flex"
              justifyContent="start"
              alignItems="center"
              gap="10px"
            >
              <LocationOnOutlined fontSize="large" sx={{ color: main }} />
              <Typography color={medium}>총 업체등록수/영업등록수</Typography>
            </Box>
            <Typography color={medium}>
              {companyCount}/{salesCount}
            </Typography>
          </Box>
          <Divider />
          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
          >
            <Box
              display="flex"
              justifyContent="start"
              alignItems="center"
              gap="10px"
            >
              <RealEstateAgentOutlinedIcon fontSize="large" sx={{ color: main }} />
              <Typography color={medium}>
                  금주 업체등록수/영업등록수
              </Typography>
            </Box>
            <Typography color={medium}>
              {weekCompanyCount}/{weekSalesCount}
            </Typography>
          </Box>
          <Divider />
          <Box
            mt="20px"
          >
            <ChartJs
              months={months}
              companys={monthCompanies}
              sales={monthSales}
            />
          </Box>
        </Box>
        <Box
          mb={isMobile ? "20px" : "0"}
        >
          <Divider/>
          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
            mt="15px"
          >
            <Box
              display="flex"
              justifyContent="start"
              alignItems="center"
              gap="10px"
            >
              <Diversity3OutlinedIcon fontSize="large" sx={{ color: main }} />
              <Typography color={medium}>전체 그룹 수</Typography>
            </Box>
            <Typography color={medium}>
              {totalGroupNums}개 그룹
            </Typography>
          </Box>
          <Divider sx={{marginTop: "15px", marginBottom: "30px"}} />
          <DoughnutWidget groupNames={groupNames} groupTotalNums={groupTotalNums} />
        </Box>
      </Box>
    </WidgetWrapper>
  );
};

export default HomeWidget;
