import React, { useState, useEffect } from 'react';
import { Typography} from "@mui/material";

function ScrollToAppearComponent() {

  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      // 브라우저 창의 현재 세로 높이 (1페이지 분량)
      const onePageHeight = window.innerHeight;

      // 스크롤 위치가 1페이지 높이를 넘었는지 감지
      if (window.scrollY > onePageHeight) {
        setIsVisible(true);
      } else {
        setIsVisible(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    
    // 컴포넌트 해제 시 이벤트 리스너 제거
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div>

      {/* 고정 위치 컴포넌트 */}
      <div
        style={{
          // 1. 고정 위치 설정
          position: 'fixed',
          bottom: '15px',
          right: '20px',
          zIndex: 1000,
          
          // 2. 부드러운 등장 애니메이션 처리
          opacity: isVisible ? 1 : 0,
          visibility: isVisible ? 'visible' : 'hidden',
          transform: isVisible ? 'translateY(0)' : 'translateY(20px)',
          transition: 'opacity 0.4s ease, transform 0.4s ease, visibility 0.4s',

          // 3. 디자인 스타일
          backgroundColor: '#007bff',
          color: '#ffffff',
          padding: '15px 25px',
          borderRadius: '30px',
          boxShadow: '0 4px 10px rgba(0,0,0,0.2)',
          cursor: 'pointer',
          fontWeight: 'bold',

          WebkitTapHighlightColor: 'transparent',
        }}
        onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
      >
        <Typography>맨 위로 ↑</Typography>
      </div>
    </div>
  );
}

export default ScrollToAppearComponent;