import { Box, Tooltip, Typography, useMediaQuery } from "@mui/material";
import WidgetWrapper from "components/WidgetWrapper";
import { useSelector, useDispatch } from "react-redux";
import SalesPostsWidget from "scenes/widgets/SalesPostsWidget";
import SearchSalesPannel from "scenes/widgets/SearchSalesPannel";
import DownloadForOfflineIcon from "@mui/icons-material/DownloadForOffline";
import EmojiTransportationOutlinedIcon from "@mui/icons-material/EmojiTransportationOutlined";
import ExcelJS from "exceljs";
import { saveAs } from "file-saver";
import { setSalesPageMenuMode } from "state";
import { createExcelContents } from "utils";
import RegistCompanyWidget from "scenes/widgets/RegistCompanyWidget";
import ScrollToAppearComponent from "scenes/widgets/ScrollToAppearComponent";

const SearchSales = () => {

  const dispatch = useDispatch();
  const isNonMobileScreens = useMediaQuery("(min-width:1000px)");
  const { _id, picturePath } = useSelector((state) => state.user);
  const posts = useSelector((state) => state.posts);
  const totalSearchSales = useSelector((state) => state.totalSearchSales);
  const salesPageMenuMode = useSelector((state) => state.salesPageMenuMode);
  const searchMode = useSelector((state) => state.searchMode);
  const mainUser = useSelector((state) => state.mainUser);

  const download = async () => {
    if (posts.length === 0) {
      alert("엑셀파일을 생성할 데이터가 없습니다.\n먼저 데이터를 검색하세요.")
      return
    }

    if (window.confirm("엑셀파일을 생성하시겠습니까?")) {

      const workbook = new ExcelJS.Workbook();
  
      await createExcelContents(workbook, "Sheet1", posts);
  
      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      });
  
      const now = new Date();
  
      const year = now.getFullYear();
      const month = String(now.getMonth() + 1).padStart(2, "0");
      const day = String(now.getDate()).padStart(2, "0");
      const hours = String(now.getHours()).padStart(2, "0");
      const minutes = String(now.getMinutes()).padStart(2, "0");
      const seconds = String(now.getSeconds()).padStart(2, "0");
  
      // 원하는 형태로 조합 (예: 20260712_215200)
      const formattedDateTime = `${year}${month}${day}_${hours}${minutes}${seconds}_`;
  
      saveAs(blob, formattedDateTime + "sales_data.xlsx");
    }
  };

  return (
    <Box
      mt="80px"
      width="100%"
      padding="1rem 1.5rem"
      display={isNonMobileScreens ? "flex" : "block"}
      gap="1.5rem"
      justifyContent="center"
    >
      <Box flexBasis={isNonMobileScreens ? "25%" : undefined}>
        <SearchSalesPannel userId={_id} picturePath={picturePath} />
      </Box>
      <Box
        flexBasis={isNonMobileScreens ? "75%" : undefined}
        mt={isNonMobileScreens ? undefined : "2rem"}
      >
        <WidgetWrapper>
          {salesPageMenuMode === "search" ? (
            <Box pb="60px">
              <Box
                display="flex"
                justifyContent={"space-between"}
                alignItems={"center"}
              >
                {salesPageMenuMode === "search" ? (
                  <Box>
                    <Typography fontWeight={"600"}>
                      검색결과: {posts.length > 100 ? 100 : posts.length}건/
                      {totalSearchSales}건
                    </Typography>
                  </Box>
                ) : null}
                <Box display="flex" gap="10px">
                  {searchMode === "normal" && !mainUser ?  
                    <Tooltip title="업체생성">
                      <EmojiTransportationOutlinedIcon
                        sx={{
                          fontSize: "30px",
                          cursor: "pointer",
                          color: "#0073E6",
                        }}
                        onClick={() =>
                          dispatch(setSalesPageMenuMode("createCompany"))
                        }
                      />
                    </Tooltip>
                  : null}
                  <Tooltip title="엑셀다운로드">
                    <DownloadForOfflineIcon
                      sx={{
                        fontSize: "30px",
                        cursor: "pointer",
                        color: "#0073E6",
                      }}
                      onClick={() => download()}
                    />
                  </Tooltip>
                </Box>
              </Box>
              <SalesPostsWidget />
            </Box>
          ) : salesPageMenuMode === "createCompany" ||
            salesPageMenuMode === "editCompany" ? (
            <RegistCompanyWidget />
          ) : null}
        </WidgetWrapper>
      </Box>
      <ScrollToAppearComponent/>
    </Box>
  );
};

export default SearchSales;
