import {
  Box,
  Typography,
  Divider,
  useTheme,
  TextField,
  Button,
  useMediaQuery,
  RadioGroup,
  Radio,
  FormControlLabel
} from "@mui/material";
import UserImage from "components/UserImage";
import FlexBetween from "components/FlexBetween";
import WidgetWrapper from "components/WidgetWrapper";
import MenuItem from "@mui/material/MenuItem";
import FormControl from "@mui/material/FormControl";
import { useDispatch, useSelector } from "react-redux";
import { useState, useEffect} from "react";
import { setUser, setLogout, setMainUser } from "state";

const MyPageWidget = () => {
  const { palette } = useTheme();
  const token = useSelector((state) => state.token);
  const dark = palette.neutral.dark;
  const isMobile = useMediaQuery("(max-width: 600px)");

  const user = useSelector((state) => state.user);
  const mainUser = useSelector((state) => state.mainUser);
  const dispatch = useDispatch();

  const [oldPassword, setOldPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [passwordVerify, setPasswordVerify] = useState("");
  const [selectedCompanion, setSelectedCompanion] = useState({
    name: "",
    groups: [],
  });
  const [inputCompanion, setInputCompanion] = useState("");
  const [groupSelectedCompanion, setGroupSelectedCompanion] = useState({
    name: "",
    groups: [],
  });

  const [selectedGroup, setSelectedGroup] = useState("");
  const [inputGroup, setInputGroup] = useState("");
  const [userMode, setUserMode] = useState(mainUser !== "" ? "observer" : "main");
  const [mainUsers, setMainUsers] = useState([]);

  const addCompanion = async (e) => {
    if (inputCompanion === "") {
      alert("공동영업자 이름을 입력해야 합니다.");
      setInputCompanion("");
      return;
    }
    if (user.companion.some((value) => value.name === inputCompanion)) {
      alert("이미 등록된 공동영업자 입니다.");
      setInputCompanion("");
      return;
    }

    if (window.confirm("입력한 공동영업자를 정말 추가하시겠습니까?")) {
      const response = await fetch(
        `http://3.37.116.103:3500/data/addCompanion`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            userId: user._id,
            companion: inputCompanion,
          }),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }

      const data = await response.json();

      if (data) {
        dispatch(setUser(data));
        setInputCompanion("");
      }
    } else {
      return;
    }
  };

  const deleteCompanion = async (e) => {
    if (!selectedCompanion.name) {
      alert("삭제할 공동영업자를 먼저 선택하세요");
      return;
    }

    if (selectedCompanion.name === "단독") {
      alert("이 항목은 삭제할 수 없습니다");
      return;
    }

    if (window.confirm("선택한 공동영업자를 정말 삭제하시겠습니까?")) {
      const response = await fetch(
        `http://3.37.116.103:3500/data/deleteCompanion`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            userId: user._id,
            companion: selectedCompanion.name,
          }),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }

      const data = await response.json();

      if (data) {
        dispatch(setUser({ ...data }));
        setSelectedCompanion({ name: "", groups: [] });
        setInputCompanion("");
      }
    } else {
      return;
    }
  };

  const addGroup = async (e) => {
    if (!inputGroup) {
      alert("새로 등록할 그룹명을 입력하세요.");
      return;
    }

    if (groupSelectedCompanion.groups.includes(inputGroup)) {
      alert("이미 등록된 그룹 입니다.");
      setInputGroup("");
      return;
    }

    if (window.confirm("입력한 그룹을 정말 추가하시겠습니까?")) {
      const response = await fetch(`http://3.37.116.103:3500/data/addGroup`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          userId: user._id,
          companion: groupSelectedCompanion.name,
          group: inputGroup,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }

      const data = await response.json();

      if (data) {
        dispatch(setUser({ ...data }));
        setGroupSelectedCompanion({ name: "", groups: [] });
        setSelectedGroup("");
        setInputGroup("");
      }
    } else {
      return;
    }
  };

  const deleteGroup = async (e) => {
    if (!selectedGroup) {
      alert("삭제할 그룹을 선택하세요.");
      return;
    }

    if (selectedGroup === "미지정") {
      alert("이 항목은 삭제할 수 없습니다");
      return;
    }

    if (window.confirm("선택한 그룹을 정말 삭제하시겠습니까?")) {
      const response = await fetch(
        `http://3.37.116.103:3500/data/deleteGroup`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            userId: user._id,
            companion: groupSelectedCompanion.name,
            group: selectedGroup,
          }),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }

      const data = await response.json();

      if (data) {
        dispatch(setUser({ ...data }));
        setGroupSelectedCompanion({ name: "", groups: [] });
        setSelectedGroup("");
        setInputGroup("");
      }
    }
  };

  const changePassword = async () => {
    if (oldPassword === "" || newPassword === "" || passwordVerify === "") {
      alert(
        "기존 Password, 새 Password, Password 확인 값을 모두 입력해야 합니다.",
      );
      return;
    }

    if (newPassword !== passwordVerify) {
      alert("입력한 새 password와 Password 확인이 일치하지 않습니다.");
      return;
    }

    if (window.confirm("비밀번호를 변경하시겠습니까?")) {
      const response = await fetch(
        `http://3.37.116.103:3500/auth/changePassword`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            userId: user._id,
            oldPassword,
            newPassword,
            passwordVerify,
          }),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }

      const data = await response.json();
      if (!data) {
        alert("비밀번호 변경이 실패했습니다");
      } else {
        alert("비밀번호가 변경되었습니다.");
        dispatch(setLogout());
      }
    }
  };
  
  useEffect(() => {
    const getMainUsers = async () => {
  
        const response = await fetch(
          `http://3.37.116.103:3500/data/getMainUsers`,
          {
            method: "POST",
            headers: {
              Authorization: `Bearer ${token}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              userId: user._id,
              userName: user.name
            }),
          },
        );
  
        if (!response.ok) {
          const error = await response.json();
          alert(error);
          return;
        }
        const data = await response.json();
        setMainUsers(data)
    };
    getMainUsers()
  }, [token, user._id, user.name])


  return (
    <WidgetWrapper>
      <Typography mb="20px" sx={{ fontSize: "18px", fontWeight: 600 }}>
        MyPage
      </Typography>
      {/* FIRST ROW */}
      <FlexBetween gap="0.5rem" pb="1.1rem">
        <FlexBetween gap="1rem">
          <UserImage image={user.picturePath} />
          <Box>
            <Typography variant="h4" color={dark} fontWeight="500">
              {user.name}
            </Typography>
          </Box>
        </FlexBetween>
      </FlexBetween>

      <Divider />
      <Typography
        m="20px 0px"
        sx={{ fontSize: "18px", color: "#999", fontWeight: 600 }}
      >
        사용자 모드 선택
      </Typography>
      {/* SECOND ROW */}
      <Box
        mb="10px"
        p="1rem 1rem"
        display={ isMobile ? "block" : "flex"}
        justifyContent={"start"}
        alignItems={"center"}
        gap="15px"
      >
        <FormControl sx={{marginBottom: "15px"}}>
          <RadioGroup
            row
            name="userMode"
            value={userMode}
            onChange={(e) => {
              setUserMode(e.target.value)
              if (e.target.value === "main") {
                dispatch(setMainUser(""))
              } else {
                alert("동행자 모드를 선택했습니다.\n아래의 주관리자를 반드시 선택해 주세요\n동행자 모드에서는 주관리자가 작성한 정보를 검색하고, 리포팅할 수 있습니다.")
              }
            }}
          >
            <FormControlLabel
              label="주관리자"
              value="main"
              control={
                <Radio
                  sx={{
                    color: "#79058e",
                    "&.Mui-checked": {
                      color: "#79058e",
                    },
                  }}
                />
              }
            />
            <FormControlLabel
              label="동행자"
              value="observer"
              control={
                <Radio
                  sx={{
                    color: "#79058e",
                    "&.Mui-checked": {
                      color: "#79058e",
                    },
                  }}
                />
              }
            />
          </RadioGroup>
        </FormControl>
        <Box mb="15px">
        <TextField
          select
          label="주관리자 선택"
          name="companion"
          value={mainUser?.name}
          onChange={(e) => {
            const user = mainUsers?.find((item) => item?.name === e.target.value)
            dispatch(setMainUser(user))
          }}
          sx={{ width: isMobile ? "100%" : "220px" }}
          disabled={userMode === "main" ? true : false}
        >
          {mainUsers?.map((item) => (
            <MenuItem key={item?._id} value={item?.name}>
              {item?.name}
            </MenuItem>
          ))}
        </TextField>
        </Box>
      </Box>
      <Divider />
      <Typography
        m="20px 0px"
        sx={{ fontSize: "18px", color: "#999", fontWeight: 600 }}
      >
        Password 변경
      </Typography>
      {/* SECOND ROW */}
      <Box
        mb="10px"
        p="1rem 1rem"
        display={ isMobile ? "block" : "flex"}
        justifyContent={"space-between"}
        gap="15px"
      >
        <form>
          <Box
            display={ "grid"}
            gridTemplateColumns={"1fr"}
            alignItems={"center"}
            gap="15px"
          >
          <TextField
            label="기존 Password"
            type="password"
            onChange={(e) => setOldPassword(e.target.value)}
            value={oldPassword}
            name="oldPpassword"
            sx={{ width: isMobile ? "100%" : "220px" }}
          />
          <TextField
            label="새 Password"
            type="password"
            onChange={(e) => setNewPassword(e.target.value)}
            value={newPassword}
            name="newPpassword"
            sx={{ width: isMobile ? "100%" : "220px" }}
          />
          <TextField
            label="Password 확인*"
            type="password"
            onChange={(e) => setPasswordVerify(e.target.value)}
            value={passwordVerify}
            name="passwordVerify"
            sx={{ width: isMobile ? "100%" : "220px" }}
          />
        </Box>
        </form>
        <Box>
          <Button
            sx={{
              mt: isMobile ? "15px" : "0",
              p: "1rem",
              backgroundColor: "#0073E6",
              color: "#fff",
              "&:hover": { backgroundColor: "#5299e0" },
            }}
            onClick={() => changePassword()}
          >
            변경
          </Button>
        </Box>
      </Box>

      <Divider />

      <Typography
        m="20px 0px"
        sx={{ fontSize: "18px", color: "#999", fontWeight: 600 }}
      >
        공동영업 관리
      </Typography>
      <Box display="grid" gap="20px" mb="10px" p="1rem 1rem">
        <Box display="flex" justifyContent={"space-between"} gap="20px">
          <TextField
            select
            label="선택한 공동영업자"
            name="companion"
            value={selectedCompanion.name}
            onChange={(e) => {
              const who = user.companion.find((u) => u.name === e.target.value);
              setSelectedCompanion(who);
              setInputCompanion("");
            }}
            sx={{ width: isMobile ? "100%" : "220px" }}
          >
            {user.companion.map((item) => (
              <MenuItem key={item._id} value={item.name}>
                {item.name}
              </MenuItem>
            ))}
          </TextField>
          <Button
            sx={{
              p: "1rem",
              backgroundColor: "#0073E6",
              color: "#fff",
              "&:hover": { backgroundColor: "#5299e0" },
            }}
            onClick={(e) => deleteCompanion(e)}
          >
            삭제
          </Button>
        </Box>
        <Box display="flex" justifyContent={"space-between"} gap="20px">
          <TextField
            label="추가할 공동영업자 입력"
            name="inputCompanion"
            value={inputCompanion}
            onChange={(e) => setInputCompanion(e.target.value)}
            sx={{ width: isMobile ? "100%" : "220px" }}
          ></TextField>
          <Button
            sx={{
              p: "1rem",
              backgroundColor: "#0073E6",
              color: "#fff",
              "&:hover": { backgroundColor: "#5299e0" },
            }}
            onClick={(e) => addCompanion(e)}
          >
            추가
          </Button>
        </Box>
        <Box display={isMobile ? "block" : "flex"} gap="15px">
          <Box display="flex" gap="15px"></Box>
        </Box>
      </Box>

      <Divider />

      <Typography
        m="20px 0px"
        sx={{ fontSize: "18px", color: "#999", fontWeight: 600 }}
      >
        그룹 관리
      </Typography>
      <Box display="grid" gap="20px" mb="10px" p="1rem 1rem">
        <Box display="flex" justifyContent={"space-between"} gap="20px">
          <TextField
            select
            label="공동영업자 선택"
            name="companion"
            value={groupSelectedCompanion.name}
            onChange={(e) => {
              const who = user.companion.find((u) => u.name === e.target.value);
              setGroupSelectedCompanion(who);
              setSelectedGroup("");
              setInputGroup("");
            }}
            sx={{ width: isMobile ? "100%" : "220px" }}
          >
            {user.companion.map((item) => (
              <MenuItem key={item._id} value={item.name}>
                {item.name}
              </MenuItem>
            ))}
          </TextField>
        </Box>
        <Box display="flex" justifyContent={"space-between"} gap="20px">
          <TextField
            select
            label="선택한 그룹"
            name="group"
            value={selectedGroup}
            onChange={(e) => {
              setSelectedGroup(e.target.value);
              setInputGroup("");
            }}
            sx={{ width: isMobile ? "100%" : "220px" }}
          >
            {groupSelectedCompanion.groups.map((item) => (
              <MenuItem value={item}>{item}</MenuItem>
            ))}
          </TextField>
          <Button
            sx={{
              p: "1rem",
              backgroundColor: "#0073E6",
              color: "#fff",
              "&:hover": { backgroundColor: "#5299e0" },
            }}
            onClick={(e) => deleteGroup(e)}
          >
            삭제
          </Button>
        </Box>
        <Box display="flex" justifyContent={"space-between"} gap="20px">
          <TextField
            label="추가할 그룹명 입력"
            name="inputGroup"
            value={inputGroup}
            onChange={(e) => setInputGroup(e.target.value)}
            sx={{ width: isMobile ? "100%" : "220px" }}
          ></TextField>
          <Button
            sx={{
              p: "1rem",
              backgroundColor: "#0073E6",
              color: "#fff",
              "&:hover": { backgroundColor: "#5299e0" },
            }}
            onClick={(e) => addGroup(e)}
          >
            추가
          </Button>
        </Box>
      </Box>

      {/* THIRD ROW */}
      {/* <Box p="1rem 0">
        <ChartJs months={months}  companys={companys} sales={sales} />
      </Box> */}
    </WidgetWrapper>
  );
};

export default MyPageWidget;
